function startFloodedGate() {
    currentLevel = -1
    sprites.destroyAllSpritesOfKind(SpriteKind.Fire)
    sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
    duck.destroy()
    game.splash("Seal recovered!", "Carry it across the flooded gate.")
    startCrossing(3)
}

sprites.onOverlap(SpriteKind.Player, SpriteKind.CrossingExit, function (player, gate) {
    if (currentLevel == 1) {
        currentLevel = -1
        gate.destroy()
        sprites.destroyAllSpritesOfKind(SpriteKind.Cannon)
        sprites.destroyAllSpritesOfKind(SpriteKind.Fire)
        player.destroy()
        startLevelTwo()
    } else if (currentLevel == 3) {
        currentLevel = -1
        game.splash("Village seal returned", "The village is safe.")
        game.over(true)
    }
})

game.onUpdate(function () {
    if (currentLevel != 1 && currentLevel != 3) return
    const midpoint = currentLevel == 1 ? 354 : 329
    if (duck.isHittingTile(CollisionDirection.Bottom) && Math.abs(duck.x - midpoint) < 14) {
        crossingCheckpoint = midpoint
    }
    if (duck.top > 126) {
        hurt()
        duck.setPosition(crossingCheckpoint, 77)
        duck.vy = 0
    }
})

game.onUpdateInterval(950, function () {
    if (currentLevel != 1) return
    const cannons = sprites.allOfKind(SpriteKind.Cannon)
    if (cannons.length == 0) return
    for (let index = 0; index < cannons.length; index++) {
        const cannon = cannons[index]
        if (index % 2 != crossingShot % 2 || Math.abs(cannon.x - duck.x) > 160) continue
        const shot = sprites.createProjectileFromSprite(img`
            . 4 4 .
            4 5 5 2
            2 5 4 2
            . 2 2 .
        `, cannon, -65, 0)
        shot.setPosition(cannon.x - 9, cannon.y)
        shot.setKind(SpriteKind.Fire)
        shot.setFlag(SpriteFlag.AutoDestroy, false)
        shot.setFlag(SpriteFlag.DestroyOnWall, true)
        shot.lifespan = 3000
    }
    crossingShot++
})

